def check_error_rate(log_entries):
    from collections import deque
    window = deque()
    errors = 0
    for timestamp, is_error in log_entries:
        window.append((timestamp, is_error))
        if is_error: errors += 1
        while window and timestamp - window[0][0] > 60:
            _, old_err = window.popleft()
            if old_err: errors -= 1
        if len(window) >= 100 and (errors / len(window)) > 0.05:
            print('WARNING: Error rate exceeded 5%!')
This maintains a sliding window of log events and checks the ratio efficiently.

