def has_cycle(graph):
    visited, rec_stack = set(), set()
    def dfs(node):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if dfs(neighbor): return True
            elif neighbor in rec_stack: return True
        rec_stack.remove(node)
        return False
    return any(node not in visited and dfs(node) for node in graph)

import hashlib
class ConsistentHash:
    def __init__(self, nodes=None, replicas=3):
        self.replicas = replicas
        self.ring = dict()
        self.sorted_keys = []
        if nodes:
            for node in nodes: self.add_node(node)

    def _hash(self, key):
        return int(hashlib.md5(key.encode('utf-8')).hexdigest(), 16)

    def add_node(self, node):
        for i in range(self.replicas):
            virtual_key = f'{node}-{i}'
            h = self._hash(virtual_key)
            self.ring[h] = node
            self.sorted_keys.append(h)
        self.sorted_keys.sort()

    def get_node(self, key):
        if not self.ring: return None
        h = self._hash(key)
        for sk in self.sorted_keys:
            if h <= sk: return self.ring[sk]
        return self.ring[self.sorted_keys[0]]

import requests
def check_endpoints(urls):
    results = {}
    for url in urls:
        try:
            r = requests.get(url, timeout=3)
            results[url] = r.status_code == 200
        except requests.RequestException:
