def avg_prometheus_metric(metrics_text, target_metric):
    total, count = 0.0, 0
    for line in metrics_text.splitlines():
        if line.startswith(target_metric) and not line.startswith('#'):
            parts = line.split()
            if len(parts) >= 2:
                try:
                    total += float(parts[-1])
                    count += 1
                except ValueError:
                    pass
    return total / count if count > 0 else 0.0

