import time
def retry_operation(func, max_attempts=5, max_wait=30):
    for attempt in range(max_attempts):
        try:
            return func()
        except Exception:
            if attempt == max_attempts - 1:
                raise
            sleep_time = min(max_wait, 2 ** attempt)
            time.sleep(sleep_time)

import re
def parse_log_line(line):
    pattern = r'"(GET|POST|PUT|DELETE|PATCH) ([^ ]+) HTTP/[^"]+" ([0-9]{3})'
    match = re.search(pattern, line)
    if match:
        return match.groups()
    return None

