def moving_average(data, window_size):
    if len(data) < window_size:
        return []
    res = []
    curr_sum = sum(data[:window_size])
    res.append(curr_sum / window_size)
    for i in range(window_size, len(data)):
        curr_sum += data[i] - data[i - window_size]
        res.append(curr_sum / window_size)
    return res
